        p1 = head.next;
        ListNode p2 = p1.next;
        ListNode ret = head.next;
        for (int i = 0; i < k - 1; i++) {
            ListNode p3 = p2.next;
            p2.next = p1;
            p1 = p2;
            p2 = p3;
        }
        head.next = p1;
        ret.next = p2;
        return ret;
    }
